// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkLens) predicate.WorkLens {
	return predicate.WorkLens(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkLens) predicate.WorkLens {
	return predicate.WorkLens(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkLens) predicate.WorkLens {
	return predicate.WorkLens(sql.NotPredicates(p))
}
